class NcirVersionNotSupported(Exception):
    """ This particular version of NCIR is not supported yet. """


class HostNotFound(Exception):
    """ Host with given name or id was not found. """


class BadMediaType(Exception):
    """ Bad media type. """


class ComputeFault(Exception):
    """ Compute fault. """


class ServiceUnavailable(ComputeFault):
    """ Service unavailable. """


class BadRequest(ComputeFault):
    """ Bad request. """


class Unauthorized(ComputeFault):
    """ Unauthorized. """


class Forbidden(ComputeFault):
    """ Forbidden. """


class BadMethod(ComputeFault):
    """ Bad method. """


class OverLimit(ComputeFault):
    """ Over limit. """


class ItemNotFound(ComputeFault):
    """ Item not found. """
